class HashMap:
    """Hash table with chaining: put / get / remove / in / len / keys / items."""

    def __init__(self, capacity=8):
        self._buckets = [[] for _ in range(capacity)]
        self._size = 0

    def _bucket(self, key):
        return self._buckets[hash(key) % len(self._buckets)]

    def put(self, key, value):
        bucket = self._bucket(key)
        for pair in bucket:
            if pair[0] == key:
                pair[1] = value
                return
        bucket.append([key, value])
        self._size += 1
        if self._size > 0.75 * len(self._buckets):
            self._grow()

    def get(self, key, default=None):
        for k, v in self._bucket(key):
            if k == key:
                return v
        return default

    def remove(self, key):
        bucket = self._bucket(key)
        for i, pair in enumerate(bucket):
            if pair[0] == key:
                del bucket[i]
                self._size -= 1
                return True
        return False

    def __contains__(self, key):
        for k, _ in self._bucket(key):
            if k == key:
                return True
        return False

    def __len__(self):
        return self._size

    def keys(self):
        return [k for b in self._buckets for k, _ in b]

    def items(self):
        return [(k, v) for b in self._buckets for k, v in b]

    def _grow(self):
        old = self.items()
        self._buckets = [[] for _ in range(2 * len(self._buckets))]
        self._size = 0
        for k, v in old:
            self.put(k, v)


